/* Payroll has its own server permissions and never enters the shared workspace. */
(function(){'use strict';
const api=()=>window.CAGE_BACKEND,root=document.getElementById('payroll-root'),panel=root?.closest('[data-view-panel]');if(!root)return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-MW',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0));
const date=v=>v?new Date(v.length===10?v+'T12:00:00Z':v).toLocaleDateString('en-GB',{timeZone:'Africa/Blantyre',day:'numeric',month:'short',year:'numeric'}):'—';
const month=v=>new Date(v+'T12:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
const today=()=>new Date(Date.now()+7200000).toISOString().slice(0,10);
const fields=[['basic','Basic salary'],['allowances','Allowances'],['overtime','Overtime'],['bonus','Bonus'],['paye','PAYE'],['pension','Employee pension'],['advance','Salary advance recovery'],['other_deductions','Other deductions'],['employer_pension','Employer pension (separate)']];
const emptyAmounts=()=>Object.fromEntries(fields.map(([k])=>[k,0]));
const totals=a=>{const gross=['basic','allowances','overtime','bonus'].reduce((t,k)=>t+Number(a[k]||0),0),deductions=['paye','pension','advance','other_deductions'].reduce((t,k)=>t+Number(a[k]||0),0);return {gross,deductions,net:gross-deductions};};
const badge=v=>`<span class="payroll-status ${String(v).toLowerCase().replaceAll(' ','')}">${esc(v)}</span>`;
const button=(action,label,id='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}-button" data-payroll-action="${action}" data-payroll-id="${esc(id)}">${label}</button>`;
const feedback=document.getElementById('payroll-feedback');
let data=null,selected=null,tab='runs',epoch=0,loading=false,busy=false;
const dialog=document.createElement('dialog');dialog.id='payroll-dialog';dialog.className='payroll-dialog';dialog.setAttribute('aria-labelledby','payroll-dialog-title');document.body.append(dialog);
const run=()=>data?.runs?.find(r=>r.id===selected);
const person=id=>data?.people?.find(p=>p.id===id)?.name||'Staff member';
function message(text,error=false){feedback.textContent=text;feedback.className=error?'payroll-error':'payroll-muted';}
function errorText(e){return e.code==='23505'?'A payroll run already exists for this month. Refresh and open the existing run.':e.code==='40001'?e.message:e.message||'The payroll request failed. Refresh and retry.';}
function shell(title,body){dialog.innerHTML=`<div class="dialog-heading payroll-toolbar"><h2 id="payroll-dialog-title">${esc(title)}</h2>${button('close','Close')}</div>${body}<p class="payroll-error" role="alert"></p>`;if(!dialog.open)dialog.showModal();}
async function refresh(){
 if(loading||!api()?.currentProfile()?.active||api().currentProfile().role==='shared')return;
 const token=epoch;loading=true;message('Loading payroll…');
 try{const result=await api().payrollData(selected);if(token!==epoch)return;data=result;selected=data.selected||null;if(!data.manage)tab='slips';render();message('');}
 catch(e){if(token===epoch)message('Payroll could not load: '+errorText(e),true);}
 finally{if(token===epoch)loading=false;}
}
function render(){
 if(!data)return;
 const tabs=data.manage?[['runs','Monthly payroll'],['settings','Salary settings'],['slips','My payslips']]:[['slips','My payslips']];
 root.innerHTML=`<div class="payroll-tabs" role="tablist" aria-label="Payroll sections">${tabs.map(([k,label])=>`<button type="button" role="tab" aria-selected="${tab===k}" tabindex="${tab===k?0:-1}" data-payroll-tab="${k}">${label}</button>`).join('')}</div><div id="payroll-content" role="tabpanel"></div>`;
 const content=root.querySelector('#payroll-content');
 if(tab==='settings')content.innerHTML=settingsHTML();else if(tab==='slips')content.innerHTML=slipsHTML();else content.innerHTML=runsHTML();
}
function settingsHTML(){return `<div class="payroll-toolbar"><div><h3>Monthly salary settings</h3><p class="payroll-muted">MWK · Updates apply to future runs. Current payroll keeps its own snapshot.</p></div>${button('salary','Configure salary','',true)}</div><div class="payroll-notice">PAYE, pension and other deductions are entered manually and must be reviewed for each month. Employer pension is recorded separately from employee deductions.</div><div class="payroll-surface table-wrap"><table class="payroll-table"><thead><tr><th>Employee</th><th>Basic (MWK)</th><th>Net (MWK)</th><th>Future runs</th><th></th></tr></thead><tbody>${data.salaries.map(s=>`<tr><td><strong>${esc(person(s.user_id))}</strong></td><td class="payroll-numeric">${money(s.amounts.basic)}</td><td class="payroll-numeric">${money(totals(s.amounts).net)}</td><td>${badge(s.enabled?'Enabled':'Disabled')}</td><td>${button('salary','Edit',s.user_id)}</td></tr>`).join('')||'<tr><td colspan="5" class="payroll-empty">No salaries configured. Choose Configure salary to begin.</td></tr>'}</tbody></table></div>`;}
function slipsHTML(){return `<h3>Your released payslips</h3><p class="payroll-muted">Only payslips released to your account appear here. View a payslip to print or save it as PDF.</p><div class="payroll-surface">${data.slips.length?`<div class="table-wrap"><table class="payroll-table"><thead><tr><th>Pay period</th><th>Net pay (MWK)</th><th>Paid on</th><th></th></tr></thead><tbody>${data.slips.map(i=>`<tr><td><strong>${esc(month(i.period))}</strong><small>${esc(i.employee_name)}</small></td><td class="payroll-numeric">${money(i.net)}</td><td>${date(i.paid_on)}</td><td>${button('slip','View payslip',i.id)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="payroll-empty"><h3>No payslips released yet</h3><p>Your payslips will appear here once payroll has recorded payment and released them.</p></div>'}</div>`;}
function runsHTML(){
 const r=run(),items=data.items||[],sum=k=>items.reduce((t,i)=>t+Number(i[k]||0),0),outstanding=sum('net')-sum('paid');
 const toolbar=`<div class="payroll-toolbar"><label>Pay period <select id="payroll-run-select" aria-label="Pay period">${data.runs.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(month(x.period))} · ${esc(x.status)}</option>`).join('')||'<option value="">No payroll yet</option>'}</select></label>${button('create','Create monthly payroll','',true)}</div>`;
 if(!r)return toolbar+'<div class="payroll-surface payroll-empty"><h3>Start your first payroll</h3><p>Configure employee salaries, then create a monthly run for review.</p></div>';
 const actions=r.status==='Draft'?button('submit','Submit for approval','',true):r.status==='Review'&&data.approve?button('return','Return for correction')+button('approve','Approve payroll','',true):r.status==='Approved'?button('release','Release all fully paid payslips','',true):'';
 return toolbar+`<div class="payroll-summary"><article><span>Employees</span><strong>${items.length}</strong></article><article><span>Gross pay · MWK</span><strong>${money(sum('gross'))}</strong></article><article><span>Take-home pay · MWK</span><strong>${money(sum('net'))}</strong></article><article><span>Outstanding · MWK</span><strong>${money(outstanding)}</strong></article></div><div class="payroll-surface"><div class="payroll-toolbar"><div><h3>${esc(month(r.period))} ${badge(r.status)}</h3><p class="payroll-muted">${r.status==='Draft'?'Review amounts and submit for administrator approval.':r.status==='Review'?'Waiting for administrator approval. Pay amounts are locked during review.':'Approved '+date(r.approved_at)+'. Record payments, then release payslips.'}</p></div><div class="payroll-actions">${actions}</div></div><div class="table-wrap"><table class="payroll-table"><thead><tr><th>Employee</th><th>Gross</th><th>Deductions</th><th>Net</th><th>Paid</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.employee_name)}</strong><small>${esc(i.job_title||i.employee_number||'Staff member')}</small></td>${['gross','deductions','net','paid'].map(k=>`<td class="payroll-numeric">${money(i[k])}</td>`).join('')}<td>${badge(i.released_at?'Released':Number(i.paid)===Number(i.net)?'Paid':Number(i.paid)>0?'Partial':'Unpaid')}</td><td><div class="payroll-actions">${button('detail','Details',i.id)}${r.status==='Draft'?button('item','Edit',i.id):''}${r.status==='Approved'&&Number(i.paid)<Number(i.net)?button('payment','Record payment',i.id):''}${r.status==='Approved'&&Number(i.paid)===Number(i.net)&&!i.released_at?button('release','Release',i.id):''}${i.released_at?button('slip','Payslip',i.id):''}</div></td></tr>`).join('')||'<tr><td colspan="7">No employee lines.</td></tr>'}</tbody></table></div><p class="payroll-muted">All amounts in MWK. Payments are recorded here after they are made through your usual payment channel.</p></div><div class="payroll-surface"><h3>Activity history</h3>${data.activity.map(e=>`<details class="payroll-history"><summary>${esc(e.action)} · ${esc(person(e.actor_id))} · ${date(e.created_at)}</summary><pre>${esc(JSON.stringify(e.details,null,2))}</pre></details>`).join('')||'<p>No activity yet.</p>'}</div>`;
}
async function mutate(action,target,expected,payload,after){
 if(busy)return;busy=true;const token=epoch;dialog.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);dialog.querySelector('.payroll-error').textContent='';
 try{const id=await api().payrollWrite(action,target,expected,payload);if(token!==epoch)return;if(action!=='salary')selected=id;dialog.close();await refresh();if(token===epoch){window.CAGE_APP?.showToast('Payroll saved.');after?.();}}
 catch(e){if(token===epoch)dialog.querySelector('.payroll-error').textContent=errorText(e);}
 finally{if(token===epoch){busy=false;dialog.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=false);}}
}
function amountForm(title,amounts,extra,submit){
 shell(title,`<form id="payroll-amount-form">${extra}<div class="payroll-form-grid">${fields.map(([k,label])=>`<label>${label} · MWK<input name="${k}" type="number" step="0.01" min="0" max="999999999999" required value="${esc(amounts[k]??0)}"></label>`).join('')}</div><p class="payroll-muted">Employer pension is additional company cost; it does not reduce take-home pay. Statutory deductions are manually reviewed.</p><div class="payroll-live" aria-live="polite"></div><div class="payroll-actions">${button('close','Cancel')}<button type="submit" class="primary-button">Save amounts</button></div></form>`);
 const form=dialog.querySelector('form');const calculate=()=>{const a=Object.fromEntries(fields.map(([k])=>[k,Number(form.elements[k].value)])),t=totals(a);dialog.querySelector('.payroll-live').textContent=`Gross: MWK ${money(t.gross)} · Deductions: MWK ${money(t.deductions)} · Net: MWK ${money(t.net)}`;return a;};form.addEventListener('input',calculate);calculate();form.onsubmit=e=>{e.preventDefault();const a=calculate(),t=totals(a);if(t.gross<=0||t.net<0){dialog.querySelector('.payroll-error').textContent='Gross pay must be positive and deductions cannot exceed gross pay.';return;}submit(form,a);};
}
function salary(id){
 const s=data.salaries.find(x=>x.user_id===id),people=data.people.filter(p=>!data.salaries.some(s=>s.user_id===p.id)||p.id===id);
 if(!people.length){shell('Salary settings','<p>Every active employee already has salary settings. Choose Edit beside an employee.</p>');return;}
 amountForm('Monthly salary settings',s?.amounts||emptyAmounts(),`<label>Employee<select name="employee" required ${id?'disabled':''}>${people.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="payroll-check"><input name="enabled" type="checkbox" ${s?.enabled===false?'':'checked'}>Include this employee when creating future payroll runs</label>`,(f,a)=>mutate('salary',id||f.elements.employee.value,s?.revision||0,{amounts:a,enabled:f.elements.enabled.checked}));
}
function editItem(id){const i=data.items.find(x=>x.id===id),r=run();if(!i||r?.status!=='Draft')return;amountForm('Review pay · '+i.employee_name,i.amounts,`<p class="payroll-muted">${esc(month(r.period))} · Changes apply to this month only.</p><label>Adjustment note<textarea name="note" maxlength="2000" rows="2">${esc(i.note)}</textarea></label>`,(f,a)=>mutate('item',r.id,r.revision,{item_id:id,amounts:a,note:f.elements.note.value}));}
function create(){shell('Create monthly payroll',`<form><label>Pay month<input name="period" type="month" value="${today().slice(0,7)}" required></label><p class="payroll-notice">Enabled salary settings for active employees will be copied into a new draft. Review this month's PAYE, pension and salary adjustments before submitting.</p><div class="payroll-actions">${button('close','Cancel')}<button type="submit" class="primary-button">Create draft</button></div></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();mutate('create',null,0,{period:e.currentTarget.elements.period.value+'-01'});};}
function transition(action,id){
 const r=run();if(!r)return;
 const titles={submit:'Submit payroll for approval',approve:'Approve monthly payroll',return:'Return payroll for correction',release:'Release payslips'};
 const i=data.items.find(x=>x.id===id),count=data.items.filter(i=>!i.released_at&&Number(i.paid)===Number(i.net)).length;
 let body=action==='submit'?'<label class="payroll-check"><input type="checkbox" name="reviewed" required>I confirm that salary amounts, PAYE, pension, advance recovery and other deductions for this month have been reviewed.</label>':action==='return'?'<label>Reason for returning payroll<textarea name="reason" required maxlength="2000" rows="3"></textarea></label>':action==='approve'?'<p>Approval locks all salary amounts for this month. Payment records can be added after approval.</p>':`<p>${i?'Release '+esc(i.employee_name)+'’s payslip':`Release ${count} fully paid, unreleased payslip${count===1?'':'s'}`} to the employee${i?'':'s'}? Each person will see only their own payslip.</p>`;
 shell(titles[action],`<form><p><strong>${esc(month(r.period))}</strong></p>${body}<div class="payroll-actions">${button('close','Cancel')}<button class="primary-button" type="submit">${action==='approve'?'Approve':action==='release'?'Release':action==='return'?'Return for correction':'Submit'}</button></div></form>`);
 dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;mutate(action,r.id,r.revision,{reviewed:!!f.elements.reviewed?.checked,reason:f.elements.reason?.value||'',item_id:id||null});};
}
function payment(id){
 const i=data.items.find(x=>x.id===id),r=run();if(!i||r.status!=='Approved')return;const balance=Number(i.net)-Number(i.paid),paymentId=crypto.randomUUID();
 shell('Record salary payment',`<form><p><strong>${esc(i.employee_name)}</strong> · ${esc(month(r.period))}</p><div class="payroll-notice">Outstanding: <strong>MWK ${money(balance)}</strong>. Record only a payment already made. This action does not transfer funds. Payment records cannot be edited here.</div><div class="payroll-form-grid"><label>Amount · MWK<input type="number" name="amount" step="0.01" min="0.01" max="${balance.toFixed(2)}" value="${balance.toFixed(2)}" required></label><label>Payment date<input type="date" name="paid_on" value="${today()}" max="${today()}" required></label><label>Method<select name="method"><option>Bank transfer</option><option>Mobile money</option><option>Cash</option><option>Other</option></select></label><label>Transaction / voucher reference<input name="reference" required maxlength="200" placeholder="Payment reference"></label></div><label class="payroll-check"><input type="checkbox" required>I have checked that this payment was made and has not already been recorded.</label><div class="payroll-actions">${button('close','Cancel')}<button type="submit" class="primary-button">Record payment</button></div></form>`);
 dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;mutate('payment',r.id,r.revision,{item_id:id,payment_id:paymentId,amount:Number(f.elements.amount.value),paid_on:f.elements.paid_on.value,method:f.elements.method.value,reference:f.elements.reference.value.trim()});};
}
const breakdown=i=>`<table class="payroll-table"><thead><tr><th>Description</th><th class="payroll-numeric">MWK</th></tr></thead><tbody>${fields.filter(([k])=>k!=='employer_pension').map(([k,label])=>`<tr><td>${label}${['paye','pension','advance','other_deductions'].includes(k)?' (deduction)':''}</td><td class="payroll-numeric">${money(i.amounts[k])}</td></tr>`).join('')}<tr><td><strong>Gross pay</strong></td><td class="payroll-numeric">${money(i.gross)}</td></tr><tr><td><strong>Total deductions</strong></td><td class="payroll-numeric">${money(i.deductions)}</td></tr></tbody></table>`;
function detail(id){const i=data.items.find(x=>x.id===id);if(!i)return;shell('Pay details · '+i.employee_name,`<p>${esc(month(i.period))} · MWK</p>${breakdown(i)}<div class="payroll-live">Net: MWK ${money(i.net)} · Paid: MWK ${money(i.paid)} · Outstanding: MWK ${money(Number(i.net)-Number(i.paid))}</div><p>Employer pension: MWK ${money(i.amounts.employer_pension)}</p>${i.note?'<p>Adjustment note: '+esc(i.note)+'</p>':''}<h3>Recorded payments</h3>${data.payments.filter(p=>p.item_id===id).map(p=>`<div class="payroll-history"><strong>MWK ${money(p.amount)}</strong> · ${date(p.paid_on)}<p>${esc(p.method)} · ${esc(p.reference)} · ${esc(person(p.recorded_by))}</p></div>`).join('')||'<p class="payroll-muted">No payments recorded.</p>'}`);}
function slip(id){const i=[...(data.slips||[]),...(data.items||[])].find(x=>x.id===id&&x.released_at);if(!i)return;shell('Payslip',`<article class="payroll-slip"><header><div><h2 id="payroll-slip-heading">CAGE</h2><p>ABC-ABI · Area 47/1 · Lilongwe, Malawi<br>info@cagemw.com · +265 892 56 96 96</p></div><div><img src="./cage-logo.svg" alt="CAGE"><p>Salary payslip · MWK</p></div></header><h3>${esc(month(i.period))}</h3><div class="payroll-slip-meta"><div><span>Employee</span><strong>${esc(i.employee_name)}</strong></div><div><span>Employee number</span><strong>${esc(i.employee_number||'—')}</strong></div><div><span>Job title</span>${esc(i.job_title||'—')}</div><div><span>Department</span>${esc(i.department||'—')}</div></div>${breakdown(i)}<div class="payroll-slip-total"><span>Net pay</span><span>MWK ${money(i.net)}</span></div><p><strong>Paid:</strong> MWK ${money(i.paid)}${i.paid_on?' · Completed '+date(i.paid_on):' · No payment required'}</p><p>Employer pension contribution: MWK ${money(i.amounts.employer_pension)} (separate from deductions)</p><footer>Confidential · Issued to ${esc(i.employee_name)}<br>Released ${date(i.released_at)} · Reference ${esc(i.id)}<br>This payslip was generated electronically by CAGE Operations Hub.</footer></article><div class="payroll-actions">${button('close','Close')}${button('print','Print / save PDF','',true)}</div>`);dialog.setAttribute('aria-labelledby','payroll-slip-heading');}
function act(action,id){if(busy)return;if(action==='close'){dialog.close();return;}if(action==='print'){document.body.classList.add('payroll-printing');window.print();document.body.classList.remove('payroll-printing');return;}if(!data)return;if(action==='slip')return slip(id);if(!data.manage)return;if(action==='salary')salary(id);else if(action==='item')editItem(id);else if(action==='create')create();else if(action==='payment')payment(id);else if(action==='detail')detail(id);else if(['submit','approve','return','release'].includes(action))transition(action,id);}
for(const el of [root,dialog])el.addEventListener('click',e=>{const b=e.target.closest('[data-payroll-action]');if(b)act(b.dataset.payrollAction,b.dataset.payrollId);});
root.addEventListener('click',e=>{const b=e.target.closest('[data-payroll-tab]');if(b){tab=b.dataset.payrollTab;render();root.querySelector(`[data-payroll-tab="${tab}"]`)?.focus();}});
root.addEventListener('keydown',e=>{const tabs=[...root.querySelectorAll('[data-payroll-tab]')],i=tabs.indexOf(e.target);if(i<0||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;tabs[n].click();});
root.addEventListener('change',e=>{if(e.target.id==='payroll-run-select'){selected=e.target.value||null;refresh();}});
dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{document.body.classList.remove('payroll-printing');dialog.setAttribute('aria-labelledby','payroll-dialog-title');if(!busy)dialog.innerHTML='';});
window.addEventListener('afterprint',()=>document.body.classList.remove('payroll-printing'));
document.getElementById('payroll-refresh').onclick=()=>refresh();
new MutationObserver(()=>{if(panel.classList.contains('active'))refresh();}).observe(panel,{attributes:true,attributeFilter:['class']});
for(const name of ['cage:session-ready','cage:access-closed'])window.addEventListener(name,()=>{epoch++;data=null;selected=null;loading=false;busy=false;tab='runs';root.replaceChildren();dialog.close();dialog.innerHTML='';message('');if(name==='cage:session-ready'&&panel.classList.contains('active'))refresh();});
window.CAGE_PAYROLL={refresh};
if(panel.classList.contains('active'))refresh();
})();
